#!/usr/bin/env node
'use strict';

const assert = require('assert');
const fs = require('fs');
const os = require('os');
const path = require('path');
const a = require('./rbi-automation');

// Fixed after every dated fixture so future-date validation remains active and deterministic.
const NOW = '2027-01-10T05:00:00.000Z';
const SCHEDULE_NOW = '2026-11-19T05:00:00.000Z';
const CALENDAR_URL = 'https://www.mospi.gov.in/uploads/documents/releaseCalender/official-arc.pdf';
const calendarMeta = {sourceUrl:CALENDAR_URL,publishedAt:'2026-11-06'};
const calendarText = 'Advance Release Calendar 2026-27 8 Nov 2026 30th Nov Quarterly Estimates of GDP for Q2, FY 2026-27 9 Dec 2026 12th Dec All India Consumer Price Index (CPI) 10 Jan 2027 12th Jan All India Consumer Price Index (CPI) 11 Feb 2027 26th Feb Second Advance Estimates of GDP for FY 2026-27';
const scheduleRecord = (kind,date,extra) => Object.assign({indicator:kind==='inflation'?'All India Consumer Price Index (CPI)':'Gross Domestic Product (GDP)',releaseTitle:kind==='inflation'?'All India Consumer Price Index (CPI)':'Quarterly Estimates of GDP for Q3, FY 2026-27',nextReleaseDate:date,sourceUrl:CALENDAR_URL,sourcePublishedAt:'2026-11-06',verifiedAt:NOW,provenanceStatus:'verified-official-schedule',matchingBasis:kind==='inflation'?'exact CPI calendar title':'GDP title keyword and release classification'},kind==='growth'?{releaseType:'quarterly GDP',reportingPeriod:'Q3 FY2026-27'}:{},extra||{});
const prov = (url, date) => ({ sourceUrl:url, publishedAt:date, fetchedAt:NOW, verifiedAt:NOW });
const gdpProv = (frequency,date) => Object.assign(prov(frequency==='Quarterly'?a.URLS.gdpQuarterly:a.URLS.gdpAnnual,date),{publicationUrl:'https://www.mospi.gov.in/gdp-'+frequency.toLowerCase()+'-'+date+'.pdf',releaseTitle:'Official GDP release'});
const growthCalc = (current,previous) => ({value:+((current/previous-1)*100).toFixed(2),unrounded:(current/previous-1)*100,formula:'(current period / comparable previous period - 1) × 100',currentValue:current,previousValue:previous,rawUnit:'₹ Crore',displayedUnit:'%'});
const growthHistory = (frequency,label,currentReal,previousReal,currentNominal,previousNominal,date,revision) => {const short=/FY(\d{2})$/.exec(label),reference=frequency==='Quarterly'&&short?label.replace(/FY\d{2}$/,'FY20'+String(+short[1]-1).padStart(2,'0')+'-'+short[1]):'FY'+label;return {label:frequency==='Quarterly'?label:'FY'+label,referencePeriod:reference,indicatorName:'Gross Domestic Product',indicatorCode:5,kind:'actual',provenanceStatus:'verified',baseYear:'2022-23',series:'Current',frequency,revisionStatus:revision||'Provisional Estimates',realLevel:+(currentReal/100000).toFixed(2),nominalLevel:+(currentNominal/100000).toFixed(2),previousYearRealLevel:+(previousReal/100000).toFixed(2),previousYearNominalLevel:+(previousNominal/100000).toFixed(2),rawRealLevel:currentReal,rawNominalLevel:currentNominal,rawUnit:'₹ Crore',displayedUnit:'₹ lakh crore',realPriceBasis:'Constant prices',nominalPriceBasis:'Current prices',realGrowth:growthCalc(currentReal,previousReal),nominalGrowth:growthCalc(currentNominal,previousNominal),publicationDate:date,provenance:gdpProv(frequency,date)};};
const repoPoint = (date, rate, extra) => {const point=Object.assign({date,decisionDate:date,rate,publicationDate:date,resolutionUrl:'https://www.rbi.org.in/resolution-'+date,verificationStatus:'verified',sourceTitle:'RBI MPC resolution',provenance:prov('https://www.rbi.org.in/resolution-'+date,date)},extra||{});if(point.effectiveDate&&!point.effectiveDateBasis)Object.assign(point,{effectiveDateBasis:'explicit-immediate-effect',effectiveDateSourceUrl:point.resolutionUrl,effectiveDateSourceType:'RBI MPC resolution'});return point;};
const gdpPoint = (label,value,date,revision) => ({label,value,kind:'actual',provenanceStatus:'verified',classification:'constant-price real GDP',baseYear:'2022-23',series:'Current',frequency:'Quarterly',revisionStatus:revision||'Provisional Estimates',unit:'₹ Crore',publicationDate:date,provenance:prov('https://api.mospi.gov.in/gdp',date)});
const cpiPoint = (label,values,periods) => ({label,value:+(values.reduce((a,b)=>a+b,0)/values.length).toFixed(2),kind:'derived-quarterly-average',provenanceStatus:'derived',partial:values.length!==3,derivation:{method:'arithmetic mean of monthly All India Combined CPI YoY observations',formula:'sum(monthly YoY values) / observation count',observationCount:values.length,expectedObservationCount:3,observations:values.map((value,i)=>({period:periods[i],value})),sourceUrl:a.URLS.cpi,baseYear:'2024=100',series:'Current',releases:values.map((_,i)=>({period:periods[i],publishedAt:'2026-10-12',sourceUrl:'https://mospi.gov.in/cpi-'+periods[i]+'.pdf'}))}});
const cpiMonthly = (period,index,yoy) => ({period,index,yoy,geography:'All India',sector:'Combined',measure:'CPI (General)',baseYear:'2024=100',series:'Current',provenanceStatus:'verified',provenance:prov(a.URLS.cpi,'2026-10-12')});
const cpiSector = (key,period,index,yoy) => ({period,index,yoy,geography:'All India',sector:key==='rural'?'Rural':'Urban',measure:'CPI (General)',baseYear:'2024=100',series:'Current',provenanceStatus:'verified',provenance:prov(key==='rural'?a.URLS.cpiRural:a.URLS.cpiUrban,'2026-10-12')});
function stored() {
  return {
    updatedAt:'2026-10-07T05:00:00.000Z',
    repo:{history:[{date:'2026-10-07',rate:5.5}],source:'RBI'},
    mpc:{meetings:[{announce:'2026-12-04'}],source:'RBI'},
    stance:{current:'calibrated_tightening',since:'2026-10-07',source:'RBI'},
    gdp:{fy:{label:'FY2025-26',value:200,decimals:2,growth:7.5},quarter:{label:'Q1 FY2026-27',value:50,decimals:2,growth:7.8},unit:'₹ lakh crore',source:'MoSPI',projection:{actuals:[],estimates:[]}},
    cpi:{index:109.49,yoy:5.54,period:'2026-09',baseYear:'2024=100',source:'MoSPI',projection:{actuals:[],estimates:[]}},
    commentary:{asOf:'2026-10-07',source:'RBI',paragraphs:['Official decision text.']}
  };
}
function sources() {
  const rp=prov('https://www.rbi.org.in/resolution','2026-10-07');
  const gp=gdpProv('Quarterly','2026-08-31'),annualGp=gdpProv('Annual','2026-06-05');
  const qHistory=growthHistory('Quarterly','Q1 FY27',5000000,4638219,5500000,5000000,'2026-08-31','Not stated by API');
  const aHistory=growthHistory('Annual','2025-26',20000000,18604651,22000000,20000000,'2026-06-05','Provisional Estimates');
  return {
    currentRate:5.5,
    resolution:{rate:5.5,decisionDate:'2026-10-07',stance:'calibrated_tightening',gdpProjections:[{label:'Q2 FY27',value:7.2},{label:'Q3 FY27',value:6.9}],cpiProjections:[{label:'Q3 FY27',value:4.2}],commentary:['Official decision text.'],provenance:rp},
    repoHistory:[repoPoint('2025-06-06',5.5,{effectiveDate:'2025-06-06'}),repoPoint('2025-12-05',5.25),repoPoint('2026-10-07',5.5)],
    schedule:{meetings:[{announce:'2026-12-04'},{announce:'2027-02-05'}],provenance:prov('https://rbi.org.in/policy','2026-03-23')},
    gdp:{fy:{label:'FY2025-26',value:200,nominalValue:220,previousValue:186.05,decimals:2,growth:7.5,classification:'constant-price real GDP',baseYear:'2022-23',series:'Current',frequency:'Annual',revisionStatus:'Provisional Estimates',provenance:annualGp},quarter:{label:'Q1 FY2026-27',value:50,nominalValue:55,previousYearValue:46.38,decimals:2,growth:7.8,classification:'constant-price real GDP',baseYear:'2022-23',series:'Current',frequency:'Quarterly',revisionStatus:'Not stated by API',provenance:gp},unit:'₹ lakh crore',quarterlyHistory:[qHistory],annualHistory:[aHistory],projection:{actuals:[gdpPoint('Q1 FY27',7.8,'2026-08-31')]},provenance:gp},
    cpi:{index:109.49,yoy:5.54,period:'2026-09',baseYear:'2024=100',series:'Current',monthly:[cpiMonthly('2026-07',107.95,4.45),cpiMonthly('2026-08',108.74,4.83),cpiMonthly('2026-09',109.49,5.54)],sectors:{rural:cpiSector('rural','2026-09',110.11,6.08),urban:cpiSector('urban','2026-09',108.71,4.88)},projection:{actuals:[cpiPoint('Q2 FY27',[4,5,6],['2026-07','2026-08','2026-09'])]},provenance:prov(a.URLS.cpi,'2026-10-12')},
    releaseSchedules:{inflation:scheduleRecord('inflation','2027-01-12'),growth:scheduleRecord('growth','2027-02-26')}
  };
}
function migrated(){return a.buildCandidate(stored(),sources(),NOW).data;}
function outcomes(s){return {policy:{ok:true,value:{currentRate:s.currentRate,resolution:s.resolution}},schedule:{ok:true,value:s.schedule},gdp:{ok:true,value:s.gdp},cpi:{ok:true,value:s.cpi},inflationSchedule:{ok:true,value:s.releaseSchedules.inflation},growthSchedule:{ok:true,value:s.releaseSchedules.growth}};}

const tests=[];
function test(name,fn){tests.push({name,fn});}
function changed(base,mutate){const s=sources();mutate(s);return a.buildCandidate(base,s,NOW);}

test('1 no source changes creates no data change',()=>{const d=migrated();assert.strictEqual(a.buildCandidate(d,sources(),NOW).changed,false);});
test('2 valid repo-rate change appends decision',()=>{const d=migrated(),r=changed(d,s=>{s.currentRate=5.75;s.resolution.rate=5.75;s.resolution.decisionDate='2026-11-07';s.resolution.provenance=prov('https://www.rbi.org.in/new','2026-11-07');});assert.strictEqual(r.data.repo.history.at(-1).rate,5.75);});
test('3 new MPC schedule replaces schedule without duplicates',()=>{const parsed=a.parseSchedule('Mar 23, 2026 Meeting Schedule of the Monetary Policy Committee April 6-8, 2026 June 3-5, 2026 August 3-5, 2026 October 5-7, 2026 December 2-4, 2026 February 3-5, 2027','https://rbi.org.in/policy',NOW);assert.strictEqual(parsed.provenance.publishedAt,'2026-03-23');const r=changed(migrated(),s=>s.schedule.meetings.push({announce:'2027-04-07'}));assert.strictEqual(r.data.mpc.meetings.length,3);});
test('4 explicit new stance is accepted',()=>{const r=changed(migrated(),s=>{s.resolution.stance='neutral';s.resolution.decisionDate='2026-12-04';s.resolution.provenance=prov('https://www.rbi.org.in/new','2026-12-04');});assert.strictEqual(r.data.stance.current,'neutral');});
test('5 new GDP and CPI projections are merged',()=>{const r=changed(migrated(),s=>{s.resolution.gdpProjections.push({label:'Q4 FY27',value:6.8});s.resolution.cpiProjections.push({label:'Q4 FY27',value:4.1});});assert(r.data.gdp.projection.estimates.some(x=>x.label==='Q4 FY27'));assert(r.data.cpi.projection.estimates.some(x=>x.label==='Q4 FY27'));});
test('6 new CPI actual replaces current observation',()=>{const r=changed(migrated(),s=>{s.cpi.period='2026-10';s.cpi.index=110;s.cpi.yoy=5.8;s.cpi.monthly.push(cpiMonthly('2026-10',110,5.8));s.cpi.provenance=prov(a.URLS.cpi,'2026-11-12');});assert.strictEqual(r.data.cpi.period,'2026-10');});
test('7 new GDP actual is retained historically',()=>{const r=changed(migrated(),s=>{const p=gdpProv('Quarterly','2026-11-30'),point=growthHistory('Quarterly','Q2 FY27',5100000,4761905,5700000,5200000,'2026-11-30','Provisional Estimates');s.gdp.quarter={label:'Q2 FY2026-27',value:51,nominalValue:57,previousYearValue:47.62,decimals:2,growth:7.1,classification:'constant-price real GDP',baseYear:'2022-23',series:'Current',frequency:'Quarterly',revisionStatus:'Provisional Estimates',provenance:p};s.gdp.quarterlyHistory.push(point);s.gdp.projection.actuals=[gdpPoint('Q2 FY27',7.1,'2026-11-30')];s.gdp.provenance=p;});assert(r.data.gdp.projection.actuals.some(x=>x.label==='Q2 FY27'));});
test('8 actual removes estimate for the same period',()=>{const r=changed(migrated(),s=>s.gdp.projection.actuals=[gdpPoint('Q2 FY27',7.1,'2026-11-30')]);assert(!r.data.gdp.projection.estimates.some(x=>x.label==='Q2 FY27'));});
test('9 duplicate repo observations are deduplicated',()=>{const d=migrated();d.repo.history.push({date:'2026-10-07',rate:5.5});const r=a.buildCandidate(d,sources(),NOW);assert.strictEqual(r.data.repo.history.filter(x=>x.date==='2026-10-07').length,1);});
test('10 older source response is rejected',()=>{assert.throws(()=>changed(migrated(),s=>{s.currentRate=5.25;s.resolution.rate=5.25;s.resolution.decisionDate='2026-08-05';s.resolution.provenance=prov('https://www.rbi.org.in/old','2026-08-05');}),/publication regression|Older repo-rate/);});
test('11 malformed HTML and JSON are rejected',()=>{assert.throws(()=>a.parseCurrentRates('<html>broken</html>'));assert.throws(()=>a.parseReleaseList({bad:true}));});
test('12 HTTP-stage failure retains stored object',()=>{const d=migrated(),before=JSON.stringify(d);try{throw new Error('HTTP 503');}catch(_){}assert.strictEqual(JSON.stringify(d),before);});
test('13 partial source failure cannot write a candidate',()=>{const s=sources();delete s.cpi;assert.throws(()=>a.buildCandidate(migrated(),s,NOW));});
test('14 implausible numeric value is rejected',()=>{assert.throws(()=>changed(migrated(),s=>s.cpi.yoy=99),/Invalid CPI|implausible/i);});
test('15 missing publication date is rejected',()=>{const s=sources();s.cpi.provenance.publishedAt=null;assert.throws(()=>a.buildCandidate(migrated(),s,NOW),/provenance/i);});
test('16 atomic write staging failure preserves original',()=>{const dir=fs.mkdtempSync(path.join(os.tmpdir(),'rbi-atomic-')),file=path.join(dir,'data.json');fs.writeFileSync(file,'old\n');assert.throws(()=>a.atomicWriteMany([{file,content:'new\n',changed:true}],{beforeCommit(){throw new Error('simulated');}}));assert.strictEqual(fs.readFileSync(file,'utf8'),'old\n');fs.rmSync(dir,{recursive:true,force:true});});
test('17 RBI failure retains only RBI sections while newer CPI updates',()=>{const base=migrated(),s=sources(),o=outcomes(s);o.policy={ok:false,error:'simulated RBI policy failure'};o.schedule={ok:false,error:'simulated RBI schedule failure'};o.cpi.value.period='2026-10';o.cpi.value.index=110;o.cpi.value.yoy=5.8;o.cpi.value.monthly.push(cpiMonthly('2026-10',110,5.8));o.cpi.value.provenance=prov(a.URLS.cpi,'2026-11-12');const r=a.buildMergedCandidate(base,o,NOW).data;['repo','stance','mpc','commentary','gdp'].forEach(k=>assert.deepStrictEqual(r[k],base[k]));assert.strictEqual(r.cpi.period,'2026-10');assert.strictEqual(r.cpi.yoy,5.8);});
test('18 CPI failure retains CPI while newer RBI decision updates',()=>{const base=migrated(),s=sources(),o=outcomes(s);o.cpi={ok:false,error:'simulated CPI failure'};o.policy.value.currentRate=5.75;o.policy.value.resolution.rate=5.75;o.policy.value.resolution.decisionDate='2026-12-04';o.policy.value.resolution.stance='neutral';o.policy.value.resolution.provenance=prov('https://www.rbi.org.in/new','2026-12-04');const r=a.buildMergedCandidate(base,o,NOW).data;assert.deepStrictEqual(r.cpi,base.cpi);assert.strictEqual(r.repo.history.at(-1).rate,5.75);assert.strictEqual(r.stance.current,'neutral');});
test('19 GDP failure retains GDP while newer RBI and CPI update',()=>{const base=migrated(),s=sources(),o=outcomes(s);o.gdp={ok:false,error:'simulated GDP failure'};o.policy.value.currentRate=5.75;o.policy.value.resolution.rate=5.75;o.policy.value.resolution.decisionDate='2026-12-04';o.policy.value.resolution.provenance=prov('https://www.rbi.org.in/new','2026-12-04');o.cpi.value.period='2026-10';o.cpi.value.index=110;o.cpi.value.yoy=5.8;o.cpi.value.monthly.push(cpiMonthly('2026-10',110,5.8));o.cpi.value.provenance=prov(a.URLS.cpi,'2026-11-12');const r=a.buildMergedCandidate(base,o,NOW).data;assert.deepStrictEqual(r.gdp,base.gdp);assert.strictEqual(r.repo.history.at(-1).rate,5.75);assert.strictEqual(r.cpi.period,'2026-10');});
test('20 whitespace and Unicode punctuation do not change labelled rate parsing',()=>{assert.strictEqual(a.parseCurrentRates('<div>Policy\u00a0 Repo Rate :\n 5.50 %</div>'),5.5);});
test('21 reordered link attributes and unrelated links do not displace the resolution',()=>{const html='Resolution of the Monetary Policy Committee December 2 to 4, 2026 <a data-x="1" class="doc" href="/Scripts/BS_PressReleaseDisplay.aspx?prid=1">Full Document</a><a href="/Scripts/BS_PressReleaseDisplay.aspx?prid=2">Unrelated</a>';const r=a.parsePolicyIndex(html,'https://rbi.org.in/scripts/Annualpolicy.aspx');assert.strictEqual(r.publishedAt,'2026-12-04');assert(r.url.endsWith('prid=1'));});
test('22 missing optional outlook paragraph remains optional',()=>{const html='Date : December 4, 2026 After a detailed assessment of the evolving macroeconomic conditions, the MPC voted to keep the policy repo rate at 5.50 per cent. The MPC also decided to continue with the neutral stance. Growth and Inflation Outlook. Real GDP growth is projected with Q1: at 7.1 per cent. CPI inflation is projected with Q1: at 4.1 per cent.';const r=a.parseResolution(html,'https://rbi.org.in/resolution',NOW);assert.strictEqual(r.commentary.length,1);assert.strictEqual(r.rate,5.5);});
test('23 parsers fail closed without the relevant official label',()=>{assert.throws(()=>a.parseCurrentRates('<div>Standing Deposit Facility 5.25%</div>'));assert.throws(()=>a.parsePolicyIndex('<a href="/Scripts/BS_PressReleaseDisplay.aspx?prid=1">Full Document</a>','https://rbi.org.in/'));});
test('24 globally invalid merged data aborts despite isolated source failure',()=>{const base=migrated(),o=outcomes(sources());base.gdp.unit='unsupported unit';o.gdp={ok:false,error:'simulated GDP failure'};assert.throws(()=>a.buildMergedCandidate(base,o,NOW),/Invalid GDP actual/);});
test('25 schedule failure does not suppress a valid policy decision',()=>{const base=migrated(),o=outcomes(sources());o.schedule={ok:false,error:'simulated schedule failure'};o.policy.value.currentRate=5.75;o.policy.value.resolution.rate=5.75;o.policy.value.resolution.decisionDate='2026-12-04';o.policy.value.resolution.provenance=prov('https://www.rbi.org.in/new','2026-12-04');const r=a.buildMergedCandidate(base,o,NOW).data;assert.deepStrictEqual(r.mpc,base.mpc);assert.strictEqual(r.repo.history.at(-1).rate,5.75);});
test('26 generated fiscal card is neutral and contains no unsupported value',()=>{const macro=a.macroFromCandidate({items:{fiscal:{value:'5.59%'}}},migrated());assert.deepStrictEqual(macro.items.fiscal,{value:null,lines:['Source unavailable','Update time unavailable'],source:null,updatedAt:null,status:'coming-soon'});});
test('27 unverified stored repo and GDP points are removed',()=>{const d=migrated();d.repo.history.unshift({date:'2024-01-01',rate:6.5});d.gdp.projection.actuals.unshift({label:'Q4 FY26',value:7.8});const r=a.buildMergedCandidate(d,outcomes(sources()),NOW).data;assert(!r.repo.history.some(x=>x.date==='2024-01-01'));assert(!r.gdp.projection.actuals.some(x=>x.label==='Q4 FY26'));});
test('28 CPI quarterly actuals store their monthly-average derivation',()=>{const names=['July','August','September'],rows=names.map((month,i)=>({state:'All India',sector:'Combined',division:'CPI (General)',month,year:'2026',index:String(108+i),inflation:String(4+i)}));const releases=names.map((month,i)=>({title:'Consumer Price Index CPI '+month+' 2026',publishedAt:'2026-'+String(i+8).padStart(2,'0')+'-12',sourceUrl:'https://mospi.gov.in/cpi-'+month.toLowerCase()+'.pdf'}));const c=a.parseCpi({data:rows},releases,NOW);const p=c.projection.actuals[0];assert.strictEqual(p.kind,'derived-quarterly-average');assert.strictEqual(p.provenanceStatus,'derived');assert.strictEqual(p.derivation.observationCount,3);assert.strictEqual(p.derivation.observations.length,3);assert.strictEqual(p.derivation.releases.length,3);});
test('29 RBI archive discovery combines multiple financial years and deduplicates links',()=>{const one='Resolution of the Monetary Policy Committee June 4 to 6, 2025 <a href="/Scripts/BS_PressReleaseDisplay.aspx?prid=60604">Full Document</a>',two='Resolution of the Monetary Policy Committee October 5 to 7, 2026 <a class="x" href="/Scripts/BS_PressReleaseDisplay.aspx?prid=63742">Full Document</a>'+one;const links=[...a.parsePolicyLinks(one,'https://rbi.org.in/scripts/Annualpolicy.aspx'),...a.parsePolicyLinks(two,'https://rbi.org.in/scripts/Annualpolicy.aspx')];assert.strictEqual(new Set(links.map(x=>x.url)).size,2);assert(links.some(x=>x.publishedAt==='2025-06-06'));assert(links.some(x=>x.publishedAt==='2026-10-07'));});
test('30 changed and unchanged repo decisions create only rate steps',()=>{const points=[repoPoint('2025-06-06',5.5),repoPoint('2025-08-06',5.5),repoPoint('2025-12-05',5.25),repoPoint('2026-08-05',5.25),repoPoint('2026-10-07',5.5)];assert.deepStrictEqual(a.reconstructRepoHistory(points).map(x=>[x.date,x.rate]),[['2025-06-06',5.5],['2025-12-05',5.25],['2026-10-07',5.5]]);});
test('31 explicit immediate effect becomes the official effective date',()=>{const html='Date : June 6, 2025 Monetary Policy Decisions The MPC voted to reduce the policy repo rate by 50 basis points to 5.50 per cent with immediate effect. Press Release: 2025-2026/489';const p=a.parseRepoDecision(html,'https://www.rbi.org.in/resolution',NOW,{publishedAt:'2025-06-06',sourceTitle:'RBI resolution'});assert.strictEqual(p.effectiveDate,'2025-06-06');assert.strictEqual(p.releaseIdentifier,'Press Release: 2025-2026/489');});
test('32 missing effective-date language does not invent an effective date',()=>{const html='Date : December 5, 2025 Monetary Policy Decisions The MPC voted unanimously to reduce the policy repo rate to 5.25 per cent. Press Release: 2025-2026/1633';const p=a.parseRepoDecision(html,'https://www.rbi.org.in/resolution',NOW,{publishedAt:'2025-12-05',sourceTitle:'RBI resolution'});assert(!Object.prototype.hasOwnProperty.call(p,'effectiveDate'));});
test('33 official repo history reconstruction retains verified metadata',()=>{const history=a.reconstructRepoHistory([repoPoint('2025-06-06',5.5),repoPoint('2025-12-05',5.25),repoPoint('2026-10-07',5.5)]);assert(history.every(x=>x.verificationStatus==='verified'&&x.resolutionUrl&&x.provenance.sourceUrl));});
test('34 MoSPI Q4 actual replaces an unverified stored chart point',()=>{const d=migrated();d.gdp.projection.actuals=[{label:'Q4 FY26',value:7.8}];const s=sources();s.gdp.projection.actuals=[gdpPoint('Q4 FY26',7.91,'2026-06-05','Provisional Estimates'),gdpPoint('Q1 FY27',7.82,'2026-08-31')];const r=a.buildCandidate(d,s,NOW).data;const q4=r.gdp.projection.actuals.find(x=>x.label==='Q4 FY26');assert.strictEqual(q4.value,7.91);assert.strictEqual(q4.provenanceStatus,'verified');});
test('35 revised GDP records preserve revision classification',()=>{const q={data:[{indicator:'Gross Domestic Product',year:'2024-25',quarter:'Q4',current_price:'770',constant_price:'700',base_year:'2022-23',series:'Current',frequency:'Quarterly',revision:'First Revised Estimates',unit:'₹ Crore'},{indicator:'Gross Domestic Product',year:'2025-26',quarter:'Q4',current_price:'832',constant_price:'756',base_year:'2022-23',series:'Current',frequency:'Quarterly',revision:'Provisional Estimates',unit:'₹ Crore'},{indicator:'Gross Domestic Product',year:'2025-26',quarter:'Q1',current_price:'825',constant_price:'750',base_year:'2022-23',series:'Current',frequency:'Quarterly',revision:null,unit:'₹ Crore'},{indicator:'Gross Domestic Product',year:'2026-27',quarter:'Q1',current_price:'891',constant_price:'810',base_year:'2022-23',series:'Current',frequency:'Quarterly',revision:'First Revised Estimates',unit:'₹ Crore'}]},annual={data:[{indicator:'Gross Domestic Product',year:'2024-25',quarter:null,current_price:'3300',constant_price:'3000',base_year:'2022-23',series:'Current',frequency:'Annual',revision:'First Revised Estimates',unit:'₹ Crore'},{indicator:'Gross Domestic Product',year:'2025-26',quarter:null,current_price:'3564',constant_price:'3240',base_year:'2022-23',series:'Current',frequency:'Annual',revision:'Provisional Estimates',unit:'₹ Crore'}]},releases=[{title:'Press Note on Provisional Estimates of Annual GDP FY 2025-26 and Quarterly Estimates of GDP for Q4 of FY 2025-26',publishedAt:'2026-06-05',sourceUrl:'https://mospi.gov.in/q4.pdf'},{title:'Press Note on Quarterly estimates of Gross Domestic Product for Q1 of 2026-27',publishedAt:'2026-08-31',sourceUrl:'https://mospi.gov.in/q1.pdf'}];const g=a.parseGdp(q,annual,releases,NOW);assert.strictEqual(g.projection.actuals.find(x=>x.label==='Q1 FY27').revisionStatus,'First Revised Estimates');assert(g.projection.actuals.some(x=>x.label==='Q4 FY26'));});
test('36 incomplete CPI quarter is explicitly partial',()=>{const names=['October','November'],rows=names.map((month,i)=>({state:'All India',sector:'Combined',division:'CPI (General)',month,year:'2026',index:String(110+i),inflation:String(5+i)})),releases=names.map((month,i)=>({title:'Press release of CPI for '+month+' 2026',publishedAt:'2026-'+String(i+11).padStart(2,'0')+'-12',sourceUrl:'https://mospi.gov.in/'+month+'.pdf'}));const p=a.parseCpi({data:rows},releases,NOW).projection.actuals[0];assert.strictEqual(p.partial,true);assert.strictEqual(p.derivation.observationCount,2);assert.strictEqual(p.derivation.expectedObservationCount,3);});
test('37 source failure retains verified history but removes unverified points',()=>{const base=migrated();base.repo.history.unshift({date:'2024-01-01',rate:6.5});const o=outcomes(sources());o.policy={ok:false,error:'simulated archive failure'};const result=a.buildMergedCandidate(base,o,NOW).data;assert(result.repo.history.every(x=>x.verificationStatus==='verified'));assert(!result.repo.history.some(x=>x.date==='2024-01-01'));});
test('38 LAF notification discovery is dated, title-specific and deduplicated',()=>{const html='<tr><th>Dec 05, 2025</th></tr><tr><td><a href="/scripts/FS_Notification.aspx?Id=13206&fn=2752&Mode=0">Liquidity Adjustment Facility - Change in rates</a></td></tr><tr><td><a href="/scripts/FS_Notification.aspx?Id=13206&fn=2752&Mode=0">Liquidity Adjustment Facility - Change in rates</a></td></tr><tr><td><a href="/other">Unrelated notification</a></td></tr>';const links=a.parseLafNotificationLinks(html,a.URLS.rbiNotifications);assert.strictEqual(links.length,1);assert.strictEqual(links[0].notificationDate,'2025-12-05');assert(links[0].url.includes('Id=13206'));});
test('39 LAF immediate effect uses the official notification date',()=>{const html='Liquidity Adjustment Facility - Change in rates RBI/2025-26/132 FMOD.MAOG.No.153/01.01.001/2025-26 It has been decided to reduce the policy repo rate under the Liquidity Adjustment Facility from 5.50 per cent to 5.25 per cent with immediate effect.';const n=a.parseLafNotification(html,'https://www.rbi.org.in/notification',NOW,{notificationDate:'2025-12-05'});assert.strictEqual(n.effectiveDate,'2025-12-05');assert.strictEqual(n.effectiveDateBasis,'explicit-immediate-effect');assert.strictEqual(n.previousRate,5.5);assert.strictEqual(n.newRate,5.25);});
test('40 LAF explicit future effective date is preserved',()=>{const html='Liquidity Adjustment Facility - Change in rates It has been decided to increase the policy repo rate from 5.25 per cent to 5.50 per cent with effect from October 9, 2026.';const n=a.parseLafNotification(html,'https://www.rbi.org.in/notification',NOW,{notificationDate:'2026-10-07'});assert.strictEqual(n.effectiveDate,'2026-10-09');assert.strictEqual(n.effectiveDateBasis,'explicit-date');});
test('41 missing LAF effective language never invents an effective date',()=>{const html='Liquidity Adjustment Facility - Change in rates It has been decided to reduce the policy repo rate from 5.50 per cent to 5.25 per cent.';const n=a.parseLafNotification(html,'https://www.rbi.org.in/notification',NOW,{notificationDate:'2025-12-05'});assert(!Object.prototype.hasOwnProperty.call(n,'effectiveDate'));});
test('42 mismatched LAF notification date is rejected',()=>{const decisions=[repoPoint('2025-06-06',5.5),repoPoint('2025-12-05',5.25),repoPoint('2026-10-07',5.5)];const n={notificationDate:'2026-01-01',notificationUrl:'https://www.rbi.org.in/wrong',previousRate:5.5,newRate:5.25};assert.throws(()=>a.reconcileRepoNotifications(decisions,[n]),/date does not match/);});
test('43 mismatched LAF transition is rejected',()=>{const decisions=[repoPoint('2025-06-06',5.5),repoPoint('2025-12-05',5.25)];const n={notificationDate:'2025-12-05',notificationUrl:'https://www.rbi.org.in/wrong-rate',previousRate:6,newRate:5.25};assert.throws(()=>a.reconcileRepoNotifications(decisions,[n]),/transition does not match/);});
test('44 duplicate LAF notification links attach only once',()=>{const decisions=[repoPoint('2025-06-06',5.5),repoPoint('2025-12-05',5.25)],n={title:'Liquidity Adjustment Facility - Change in rates',notificationDate:'2025-12-05',notificationUrl:'https://www.rbi.org.in/notification',previousRate:5.5,newRate:5.25,direction:'reduce',effectiveDate:'2025-12-05',effectiveDateBasis:'explicit-immediate-effect',provenance:prov('https://www.rbi.org.in/notification','2025-12-05')};const result=a.reconcileRepoNotifications(decisions,[n,n]);assert.strictEqual(result.filter(x=>x.lafNotification).length,1);});
test('45 unavailable notification does not suppress a valid resolution',()=>{const decision=a.parseRepoDecision('Date : December 5, 2025 Monetary Policy Decisions The MPC voted to reduce the policy repo rate to 5.25 per cent.','https://www.rbi.org.in/resolution',NOW,{publishedAt:'2025-12-05',sourceTitle:'RBI resolution'});const result=a.reconcileRepoNotifications([decision],[]);assert.strictEqual(result[0].rate,5.25);assert(!Object.prototype.hasOwnProperty.call(result[0],'effectiveDate'));});
test('46 CPI parser stores verified monthly history and compatible sectors',()=>{const names=['August','September'],combined=names.map((month,i)=>({state:'All India',sector:'Combined',division:'CPI (General)',month,year:'2026',index:String(108+i),inflation:String(4+i)})),rural=names.map((month,i)=>({state:'All India',sector:'Rural',division:'CPI (General)',month,year:'2026',index:String(109+i),inflation:String(5+i)})),urban=names.map((month,i)=>({state:'All India',sector:'Urban',division:'CPI (General)',month,year:'2026',index:String(107+i),inflation:String(3+i)})),releases=names.map((month,i)=>({title:'Consumer Price Index CPI '+month+' 2026',publishedAt:'2026-'+String(i+9).padStart(2,'0')+'-12',sourceUrl:'https://mospi.gov.in/'+month+'.pdf'})),c=a.parseCpi({data:combined},releases,NOW,{rural:{data:rural},urban:{data:urban}});assert.strictEqual(c.monthly.length,2);assert.strictEqual(c.sectors.rural.sector,'Rural');assert.strictEqual(c.sectors.urban.sector,'Urban');});
test('47 optional rural failure does not suppress headline or urban CPI',()=>{const combined={data:[{state:'All India',sector:'Combined',division:'CPI (General)',month:'September',year:'2026',index:'109',inflation:'5'}]},urban={data:[{state:'All India',sector:'Urban',division:'CPI (General)',month:'September',year:'2026',index:'108',inflation:'4'}]},releases=[{title:'Consumer Price Index CPI September 2026',publishedAt:'2026-10-12',sourceUrl:'https://mospi.gov.in/sep.pdf'}],c=a.parseCpi(combined,releases,NOW,{urban});assert.strictEqual(c.yoy,5);assert(!c.sectors.rural);assert.strictEqual(c.sectors.urban.yoy,4);});
test('48 malformed sector data is omitted before parsing and cannot damage headline CPI',()=>{const s=sources(),c=a.parseCpi({data:s.cpi.monthly.map(p=>({state:'All India',sector:'Combined',division:'CPI (General)',month:{'07':'July','08':'August','09':'September'}[p.period.slice(-2)],year:'2026',index:String(p.index),inflation:String(p.yoy)}))},[{title:'CPI July 2026',publishedAt:'2026-08-12',sourceUrl:'https://mospi.gov.in/jul.pdf'},{title:'CPI August 2026',publishedAt:'2026-09-12',sourceUrl:'https://mospi.gov.in/aug.pdf'},{title:'CPI September 2026',publishedAt:'2026-10-12',sourceUrl:'https://mospi.gov.in/sep.pdf'}],NOW,{});assert.strictEqual(c.period,'2026-09');assert.deepStrictEqual(c.sectors,{});});
test('49 duplicate CPI month fails closed',()=>{const row={state:'All India',sector:'Combined',division:'CPI (General)',month:'September',year:'2026',index:'109',inflation:'5'},release=[{title:'CPI September 2026',publishedAt:'2026-10-12',sourceUrl:'https://mospi.gov.in/sep.pdf'}];assert.throws(()=>a.parseCpi({data:[row,row]},release,NOW),/duplicate/);});
test('50 invalid CPI chart point fails global validation',()=>{const d=migrated();d.cpi.monthly[0].yoy=99;assert.throws(()=>a.validateDataset(d,NOW),/monthly observation/);});
test('51 failed optional sector retains its last-known-good section',()=>{const base=migrated(),s=sources();delete s.cpi.sectors.rural;const result=a.buildCandidate(base,s,NOW).data;assert.deepStrictEqual(result.cpi.sectors.rural,base.cpi.sectors.rural);assert.strictEqual(result.cpi.sectors.urban.sector,'Urban');});
test('52 one-month partial average retains matching RBI projection',()=>{const partial=cpiPoint('Q3 FY27',[6.09],['2026-10']),projection={label:'Q3 FY27',value:6,kind:'projection',provenance:prov('https://www.rbi.org.in/resolution','2026-10-07')},merged=a.mergeProjection(null,[partial],[projection],'CPI');assert.strictEqual(merged.actuals[0].partial,true);assert.strictEqual(merged.estimates[0].label,'Q3 FY27');});
test('53 two-month partial average retains matching RBI projection',()=>{const partial=cpiPoint('Q3 FY27',[6.09,5.8],['2026-10','2026-11']),projection={label:'Q3 FY27',value:6,kind:'projection',provenance:prov('https://www.rbi.org.in/resolution','2026-10-07')},merged=a.mergeProjection(null,[partial],[projection],'CPI');assert.strictEqual(merged.actuals[0].derivation.observationCount,2);assert.strictEqual(merged.estimates.length,1);});
test('54 complete three-month average supersedes matching projection',()=>{const complete=cpiPoint('Q3 FY27',[6.09,5.8,5.7],['2026-10','2026-11','2026-12']),projection={label:'Q3 FY27',value:6,kind:'projection',provenance:prov('https://www.rbi.org.in/resolution','2026-10-07')},merged=a.mergeProjection(null,[complete],[projection],'CPI');assert.strictEqual(complete.partial,false);assert.strictEqual(merged.estimates.length,0);});
test('55 partial average remains valid when no projection is available',()=>{const partial=cpiPoint('Q3 FY27',[6.09],['2026-10']),merged=a.mergeProjection(null,[partial],[],'CPI');assert.strictEqual(merged.actuals.length,1);assert.strictEqual(merged.estimates.length,0);});
test('56 projection with invalid provenance fails global validation',()=>{const s=sources();s.resolution.cpiProjections=[{label:'Q3 FY27',value:6}];s.resolution.provenance={sourceUrl:'https://example.com/unofficial',publishedAt:'2026-10-07',fetchedAt:NOW,verifiedAt:NOW};assert.throws(()=>a.buildCandidate(migrated(),s,NOW),/Projection provenance|provenance/i);});
test('57 partial-to-complete transition removes matching projection without duplication',()=>{const projection={label:'Q3 FY27',value:6,kind:'projection',provenance:prov('https://www.rbi.org.in/resolution','2026-10-07')},partial=cpiPoint('Q3 FY27',[6.09],['2026-10']),first=a.mergeProjection(null,[partial],[projection],'CPI'),complete=cpiPoint('Q3 FY27',[6.09,5.8,5.7],['2026-10','2026-11','2026-12']),second=a.mergeProjection(first,[complete],first.estimates,'CPI');assert.strictEqual(second.actuals.filter(x=>x.label==='Q3 FY27').length,1);assert.strictEqual(second.actuals[0].partial,false);assert.strictEqual(second.estimates.filter(x=>x.label==='Q3 FY27').length,0);});
test('58 quarterly GDP calculation retains raw comparable values and formula',()=>{const p=migrated().gdp.quarterlyHistory[0];assert.strictEqual(p.realGrowth.currentValue,p.rawRealLevel);assert.strictEqual(p.realGrowth.value,+((p.realGrowth.currentValue/p.realGrowth.previousValue-1)*100).toFixed(2));assert.strictEqual(p.realGrowth.formula,'(current period / comparable previous period - 1) × 100');});
test('59 annual GDP calculation remains separate from quarterly records',()=>{const d=migrated(),p=d.gdp.annualHistory[0];assert.strictEqual(p.frequency,'Annual');assert.strictEqual(p.realGrowth.currentValue,p.rawRealLevel);assert.notStrictEqual(p.realGrowth.currentValue,d.gdp.quarterlyHistory[0].realGrowth.currentValue);});
test('60 current and constant price bases cannot be interchanged',()=>{const d=migrated();d.gdp.quarterlyHistory[0].realPriceBasis='Current prices';assert.throws(()=>a.validateDataset(d,NOW),/classification/);});
test('61 annual and quarterly frequency classifications cannot be interchanged',()=>{const d=migrated();d.gdp.annualHistory[0].frequency='Quarterly';assert.throws(()=>a.validateDataset(d,NOW),/classification/);});
test('62 crore to lakh-crore conversion is validated',()=>{const d=migrated(),p=d.gdp.quarterlyHistory[0];assert.strictEqual(p.realLevel,+((p.rawRealLevel/100000).toFixed(2)));p.realLevel+=1;assert.throws(()=>a.validateDataset(d,NOW),/level|calculation/);});
test('63 older GDP revision cannot replace a newer revision',()=>{const d=migrated();d.gdp.quarterlyHistory[0].revisionStatus='Final Estimates';assert.throws(()=>a.buildCandidate(d,sources(),NOW),/revision regression/);});
test('64 duplicate GDP periods fail global validation',()=>{const d=migrated();d.gdp.quarterlyHistory.push(JSON.parse(JSON.stringify(d.gdp.quarterlyHistory[0])));assert.throws(()=>a.validateDataset(d,NOW),/duplicated/);});
test('65 malformed GDP indicator code fails global validation',()=>{const d=migrated();d.gdp.quarterlyHistory[0].indicatorCode=4;assert.throws(()=>a.validateDataset(d,NOW),/classification/);});
test('66 invalid GDP base year fails global validation',()=>{const d=migrated();d.gdp.annualHistory[0].baseYear='2011-12';assert.throws(()=>a.validateDataset(d,NOW),/classification/);});
test('67 implausible GDP growth fails global validation',()=>{const d=migrated(),p=d.gdp.quarterlyHistory[0];p.rawRealLevel=p.realGrowth.previousValue*1.5;p.realLevel=+(p.rawRealLevel/100000).toFixed(2);p.realGrowth.currentValue=p.rawRealLevel;p.realGrowth.unrounded=50;p.realGrowth.value=50;assert.throws(()=>a.validateDataset(d,NOW),/implausible/);});
test('68 a matching actual removes only its projection and retains future projections',()=>{const actual=gdpPoint('Q2 FY27',7.1,'2026-11-30'),matched={label:'Q2 FY27',value:7.2,kind:'projection',provenance:prov('https://www.rbi.org.in/resolution','2026-10-07')},future={label:'Q3 FY27',value:6.9,kind:'projection',provenance:matched.provenance},merged=a.mergeProjection(null,[actual],[matched,future],'GDP');assert(!merged.estimates.some(x=>x.label==='Q2 FY27'));assert(merged.estimates.some(x=>x.label==='Q3 FY27'));});

test('69 valid future CPI release announcement is parsed from the official calendar',()=>{const r=a.parseReleaseSchedules(calendarText,calendarMeta,SCHEDULE_NOW,SCHEDULE_NOW);assert.strictEqual(r.inflation.nextReleaseDate,'2026-12-12');assert.strictEqual(r.inflation.indicator,'All India Consumer Price Index (CPI)');assert(!r.inflation.reportingPeriod);});
test('70 valid future GDP release announcement retains its official classification and period',()=>{const r=a.parseReleaseSchedules(calendarText,calendarMeta,SCHEDULE_NOW,SCHEDULE_NOW);assert.strictEqual(r.growth.nextReleaseDate,'2026-11-30');assert.strictEqual(r.growth.releaseType,'quarterly GDP');assert.strictEqual(r.growth.reportingPeriod,'Q2 FY2026-27');});
test('71 no announcement available returns neutral null schedules',()=>{const r=a.parseReleaseSchedules('Advance Release Calendar 2026-27 9 Dec 2026 15th Dec Monthly Bulletin of PLFS',calendarMeta,SCHEDULE_NOW,SCHEDULE_NOW);assert.deepStrictEqual(r,{inflation:null,growth:null});});
test('72 expired announcement is not returned as upcoming',()=>{const r=a.parseReleaseSchedules('Advance Release Calendar 2026-27 8 Nov 2026 12th Nov All India Consumer Price Index (CPI)',calendarMeta,SCHEDULE_NOW,SCHEDULE_NOW);assert.strictEqual(r.inflation,null);});
test('73 invalid calendar dates fail closed',()=>{assert.throws(()=>a.parseReleaseSchedules('Advance Release Calendar 2026-27 2 Feb 2027 31st Feb All India Consumer Price Index (CPI)',calendarMeta,SCHEDULE_NOW,SCHEDULE_NOW),/Invalid calendar date/);});
test('74 non-MoSPI calendar source is rejected',()=>{assert.throws(()=>a.parseReleaseSchedules(calendarText,{sourceUrl:'https://example.com/calendar.pdf'},SCHEDULE_NOW,SCHEDULE_NOW),/provenance/);});
test('75 ambiguous schedule matches are rejected',()=>{const text='Advance Release Calendar 2026-27 9 Dec 2026 12th Dec All India Consumer Price Index (CPI) 12th Dec All India Consumer Price Index (CPI) revised';assert.throws(()=>a.parseReleaseSchedules(text,calendarMeta,SCHEDULE_NOW,SCHEDULE_NOW),/Ambiguous or duplicate inflation/);});
test('76 duplicate schedule matches are rejected',()=>{const text='Advance Release Calendar 2026-27 9 Dec 2026 12th Dec All India Consumer Price Index (CPI) 12th Dec All India Consumer Price Index (CPI)';assert.throws(()=>a.parseReleaseSchedules(text,calendarMeta,SCHEDULE_NOW,SCHEDULE_NOW),/Ambiguous or duplicate inflation/);});
test('77 CPI schedule failure retains CPI observations',()=>{const base=migrated(),o=outcomes(sources());o.inflationSchedule={ok:false,error:'calendar unavailable'};const r=a.buildMergedCandidate(base,o,NOW).data;assert.deepStrictEqual(r.cpi,base.cpi);assert.deepStrictEqual(r.releaseSchedules.inflation,base.releaseSchedules.inflation);});
test('78 GDP schedule failure retains GDP observations',()=>{const base=migrated(),o=outcomes(sources());o.growthSchedule={ok:false,error:'calendar unavailable'};const r=a.buildMergedCandidate(base,o,NOW).data;assert.deepStrictEqual(r.gdp,base.gdp);assert.deepStrictEqual(r.releaseSchedules.growth,base.releaseSchedules.growth);});
test('79 CPI and GDP schedules update independently',()=>{const base=migrated(),o=outcomes(sources());o.inflationSchedule={ok:true,value:null};o.growthSchedule={ok:false,error:'GDP schedule parse failure'};const r=a.buildMergedCandidate(base,o,NOW).data;assert(!r.releaseSchedules.inflation);assert.deepStrictEqual(r.releaseSchedules.growth,base.releaseSchedules.growth);});
test('80 last-known-good future schedule is retained on source failure',()=>{const base=migrated(),o=outcomes(sources());o.inflationSchedule={ok:false,error:'timeout'};const r=a.buildMergedCandidate(base,o,'2027-01-11T05:00:00.000Z').data;assert.strictEqual(r.releaseSchedules.inflation.nextReleaseDate,'2027-01-12');});
test('81 expired last-known-good schedule is removed on source failure',()=>{const base=migrated(),o=outcomes(sources());o.inflationSchedule={ok:false,error:'timeout'};const r=a.buildMergedCandidate(base,o,'2027-01-13T05:00:00.000Z').data;assert(!r.releaseSchedules.inflation);});
test('82 missing reporting period is valid only when the calendar omits it',()=>{const r=a.parseReleaseSchedules('Advance Release Calendar 2026-27 9 Dec 2026 12th Dec All India Consumer Price Index (CPI)',calendarMeta,SCHEDULE_NOW,SCHEDULE_NOW);assert.strictEqual(r.inflation.reportingPeriod,undefined);assert(a.validReleaseSchedule(r.inflation,'inflation',SCHEDULE_NOW));});
test('83 missing source publication date remains valid and is not invented',()=>{const r=a.parseReleaseSchedules(calendarText,{sourceUrl:CALENDAR_URL},SCHEDULE_NOW,SCHEDULE_NOW);assert(!r.inflation.sourcePublishedAt);assert(a.validReleaseSchedule(r.inflation,'inflation',SCHEDULE_NOW));});
test('84 complete schedule-source failure retains only still-future schedules',()=>{const base=migrated(),o=outcomes(sources());o.inflationSchedule={ok:false,error:'complete failure'};o.growthSchedule={ok:false,error:'complete failure'};const r=a.buildMergedCandidate(base,o,'2027-01-13T05:00:00.000Z').data;assert(!r.releaseSchedules.inflation);assert.strictEqual(r.releaseSchedules.growth.nextReleaseDate,'2027-02-26');});
test('85 identical official schedule dry run creates no JSON change',()=>{const base=migrated(),s=sources();s.releaseSchedules.inflation.verifiedAt='2027-01-10T06:00:00.000Z';s.releaseSchedules.growth.verifiedAt='2027-01-10T06:00:00.000Z';assert.strictEqual(a.buildCandidate(base,s,NOW).changed,false);});

const cpiRow=(month,year,inflation,extra)=>Object.assign({state:'All India',sector:'Combined',division:'CPI (General)',month,year:String(year),index:'104.45',inflation},extra||{});
const cpiRelease=(month,year)=>{const monthNumber={January:1,February:2,March:3,December:12}[month];return {title:'Press release of CPI for '+month+' '+year,publishedAt:String(monthNumber===12?year+1:year)+'-'+String(monthNumber===12?1:monthNumber+1).padStart(2,'0')+'-12',sourceUrl:'https://www.mospi.gov.in/cpi-'+month.toLowerCase()+'-'+year+'.pdf'};};
test('86 blank CPI YoY is rejected rather than coerced to zero',()=>{assert.deepStrictEqual(a.parseCpiRows({data:[cpiRow('January',2026,'')]} ,'Combined'),[]);});
test('87 null CPI YoY is rejected rather than coerced to zero',()=>{assert.deepStrictEqual(a.parseCpiRows({data:[cpiRow('January',2026,null)]},'Combined'),[]);});
test('88 missing CPI YoY is rejected rather than coerced to zero',()=>{const row=cpiRow('January',2026,'2.74');delete row.inflation;assert.deepStrictEqual(a.parseCpiRows({data:[row]},'Combined'),[]);});
test('89 explicit official string zero remains a valid observation',()=>{const c=a.parseCpi({data:[cpiRow('January',2026,'0.00')]},[cpiRelease('January',2026)],NOW);assert.strictEqual(c.yoy,0);assert.strictEqual(c.monthly[0].yoy,0);});
test('90 December 2025 transition observation is excluded from the current series',()=>{const rows=a.parseCpiRows({data:[cpiRow('December',2025,'0.00'),cpiRow('January',2026,'2.74')]} ,'Combined');assert.deepStrictEqual(rows.map(row=>row.period),['2026-01']);});
test('91 January 2026 current-base observation is retained at 2.74 percent',()=>{const rows=a.parseCpiRows({data:[cpiRow('January',2026,'2.74')]} ,'Combined');assert.strictEqual(rows[0].period,'2026-01');assert.strictEqual(rows[0].yoy,2.74);});
test('92 mixed-base observations cannot share one current trend',()=>{const rows=a.parseCpiRows({data:[cpiRow('January',2026,'1.33',{base_year:'2012=100'}),cpiRow('February',2026,'3.21',{base_year:'2024=100'})]},'Combined');assert.deepStrictEqual(rows.map(row=>row.period),['2026-02']);});
test('93 quarterly average excludes incompatible old-base observations',()=>{const rows=[cpiRow('December',2025,'1.33',{base_year:'2012=100'}),cpiRow('January',2026,'2.74'),cpiRow('February',2026,'3.21'),cpiRow('March',2026,'3.44')],releases=[cpiRelease('January',2026),cpiRelease('February',2026),cpiRelease('March',2026)],c=a.parseCpi({data:rows},releases,NOW),q4=c.projection.actuals.find(point=>point.label==='Q4 FY26');assert.strictEqual(q4.derivation.observationCount,3);assert.deepStrictEqual(q4.derivation.observations.map(point=>point.period),['2026-01','2026-02','2026-03']);assert.strictEqual(q4.value,3.13);});
test('94 explicit official numeric zero remains supported',()=>{const c=a.parseCpi({data:[cpiRow('January',2026,0)]},[cpiRelease('January',2026)],NOW);assert.strictEqual(c.monthly[0].yoy,0);});
test('95 CPI failure retains only compatible verified observations',()=>{const base=migrated();base.cpi.monthly.unshift(Object.assign(cpiMonthly('2025-12',104.1,0),{baseYear:'2012=100',series:'Legacy'}));const o=outcomes(sources());o.cpi={ok:false,error:'simulated CPI source failure'};const c=a.buildMergedCandidate(base,o,NOW).data.cpi;assert(c.monthly.every(point=>point.period>='2026-01'&&point.baseYear==='2024=100'&&point.series==='Current'));assert(!c.monthly.some(point=>point.period==='2025-12'));});

function eightQuarterFixture(){
  const periods=[['2023-24','Q2'],['2023-24','Q3'],['2023-24','Q4'],['2024-25','Q1'],['2024-25','Q2'],['2024-25','Q3'],['2024-25','Q4'],['2025-26','Q1'],['2025-26','Q2'],['2025-26','Q3'],['2025-26','Q4'],['2026-27','Q1']];
  const rows=periods.map((item,index)=>({indicator:'Gross Domestic Product',year:item[0],quarter:item[1],current_price:String(6500000+index*390000),constant_price:String(6200000+index*350000),base_year:'2022-23',series:'Current',frequency:'Quarterly',revision:index%3===0?'First Revised Estimates':index%3===1?'Provisional Estimates':null,unit:'\u20b9 Crore'})).reverse();
  const annual={data:[{indicator:'Gross Domestic Product',year:'2024-25',quarter:null,current_price:'30000000',constant_price:'28000000',base_year:'2022-23',series:'Current',frequency:'Annual',revision:'First Revised Estimates',unit:'\u20b9 Crore'},{indicator:'Gross Domestic Product',year:'2025-26',quarter:null,current_price:'32500000',constant_price:'30100000',base_year:'2022-23',series:'Current',frequency:'Annual',revision:'Provisional Estimates',unit:'\u20b9 Crore'}]};
  const releases=[{title:'Press Note on new series of GDP estimates with base year 2022-23',publishedAt:'2026-02-27',sourceUrl:'https://www.mospi.gov.in/new-gdp-series.pdf'},{title:'Press Note on Provisional Estimates of Annual GDP FY 2025-26 and Quarterly Estimates of GDP for Q4 of FY 2025-26',publishedAt:'2026-06-05',sourceUrl:'https://www.mospi.gov.in/q4-2025-26.pdf'},{title:'Press Release on additional information related to GDP estimates received after release of Q1 Estimates of FY 2026-27',publishedAt:'2026-09-02',sourceUrl:'https://www.mospi.gov.in/q1-2026-27.pdf'}];
  return {quarterly:{data:rows},annual,releases};
}
test('96 official GDP parser retains the latest eight comparable quarters',()=>{const f=eightQuarterFixture(),g=a.parseGdp(f.quarterly,f.annual,f.releases,NOW);assert.strictEqual(g.quarterlyHistory.length,8);assert.strictEqual(g.quarterlyHistory[0].referencePeriod,'Q2 FY2024-25');assert.strictEqual(g.quarterlyHistory.at(-1).referencePeriod,'Q1 FY2026-27');});
test('97 eight-quarter GDP history is sorted chronologically',()=>{const f=eightQuarterFixture(),g=a.parseGdp(f.quarterly,f.annual,f.releases,NOW),periods=g.quarterlyHistory.map(point=>point.referencePeriod);assert.deepStrictEqual(periods,['Q2 FY2024-25','Q3 FY2024-25','Q4 FY2024-25','Q1 FY2025-26','Q2 FY2025-26','Q3 FY2025-26','Q4 FY2025-26','Q1 FY2026-27']);});
test('98 duplicate GDP quarters fail closed before history construction',()=>{const f=eightQuarterFixture();f.quarterly.data.push({...f.quarterly.data[0]});assert.throws(()=>a.parseGdp(f.quarterly,f.annual,f.releases,NOW),/duplicate/);});
test('99 incompatible GDP base years fail closed',()=>{const f=eightQuarterFixture();f.quarterly.data[0].base_year='2011-12';assert.throws(()=>a.parseGdp(f.quarterly,f.annual,f.releases,NOW),/classification/);});
test('100 different official GDP revision stages remain attached to observations',()=>{const f=eightQuarterFixture(),g=a.parseGdp(f.quarterly,f.annual,f.releases,NOW);assert(new Set(g.quarterlyHistory.map(point=>point.revisionStatus)).size>1);});
test('101 a quarter missing its prior-year comparison is excluded',()=>{const f=eightQuarterFixture();f.quarterly.data=f.quarterly.data.filter(row=>!(row.year==='2023-24'&&row.quarter==='Q2'));const g=a.parseGdp(f.quarterly,f.annual,f.releases,NOW);assert(!g.quarterlyHistory.some(point=>point.referencePeriod==='Q2 FY2024-25'));});
test('102 an older-period GDP regression is rejected',()=>{const base=migrated(),s=sources(),point=growthHistory('Quarterly','Q2 FY27',5100000,4761905,5700000,5200000,'2026-11-30','Provisional Estimates');s.gdp.quarterlyHistory=[point];s.gdp.quarter={...s.gdp.quarter,label:'Q2 FY2026-27',provenance:gdpProv('Quarterly','2026-11-30')};s.gdp.projection.actuals=[gdpPoint('Q2 FY27',point.realGrowth.value,'2026-11-30')];s.gdp.provenance=s.gdp.quarter.provenance;assert.throws(()=>a.buildCandidate(base,s,NOW),/older-period regression/);});
test('103 GDP source failure retains the complete last-known-good history',()=>{const base=migrated(),o=outcomes(sources());o.gdp={ok:false,error:'simulated GDP timeout'};assert.deepStrictEqual(a.buildMergedCandidate(base,o,NOW).data.gdp.quarterlyHistory,base.gdp.quarterlyHistory);});

(async()=>{
  let failed=0;
  for(const t of tests){try{await t.fn();console.log('PASS',t.name);}catch(error){failed++;console.error('FAIL',t.name,'-',error.message);}}
  console.log((tests.length-failed)+'/'+tests.length+' deterministic tests passed');
  if(failed)process.exitCode=1;
})();
